PUT /products/_doc/1
{ "name": "Blue pen", "price": 1.5, "tags": ["office"], "stock": 10 }
# { "_id": "1", "_version": 1, "result": "created", "_seq_no": 0, "_primary_term": 1 }

POST /products/_update/1
{ "doc": { "price": 1.2 } }
# { "_version": 2, "result": "updated", ... }

POST /products/_update/1
{ "script": { "source": "ctx._source.stock -= params.n", "params": { "n": 3 } } }

GET /products/_doc/1
# { "_version": 3, "_seq_no": 2, "found": true,
#   "_source": { "name": "Blue pen", "price": 1.2, "tags": ["office"], "stock": 7 } }

PUT /products/_doc/1?if_seq_no=1&if_primary_term=1
{ "name": "Stale write" }
# 409 version_conflict_engine_exception

PUT /orders
{
  "mappings": {
    "dynamic": "strict",
    "properties": {
      "order_id":  { "type": "keyword" },
      "status":    { "type": "keyword" },
      "customer":  { "type": "text", "fields": { "raw": { "type": "keyword" } } },
      "total":     { "type": "scaled_float", "scaling_factor": 100 },
      "placed_at": { "type": "date" },
      "notes":     { "type": "text" }
    }
  }
}

PUT /orders/_doc/1
{ "order_id": "A-1", "status": "paid", "customer": "Ana Petrosyan", "colour": "red" }
# 400 strict_dynamic_mapping_exception: [colour] not allowed

GET /orders/_mapping

GET /orders/_search
{
  "query": {
    "bool": {
      "filter": [
        { "terms": { "status": ["paid", "shipped"] } },
        { "range": { "total": { "gte": 20, "lt": 100 } } },
        { "range": { "placed_at": { "gte": "now-7d/d", "lt": "now/d" } } },
        { "exists": { "field": "notes" } }
      ]
    }
  }
}

# Gotcha: term on an analyzed text field
GET /orders/_search
{ "query": { "term": { "customer": "Ana Petrosyan" } } }        # 0 hits
GET /orders/_search
{ "query": { "term": { "customer.raw": "Ana Petrosyan" } } }    # 1 hit

GET /products/_search
{
  "query": {
    "bool": {
      "must":     [ { "multi_match": { "query": "gel pen", "fields": ["name^3", "description"] } } ],
      "filter":   [ { "term": { "category": "office" } },
                    { "range": { "price": { "lte": 10 } } } ],
      "should":   [ { "term": { "on_sale": { "value": true, "boost": 2 } } } ],
      "must_not": [ { "term": { "discontinued": true } } ]
    }
  }
}
# matches need the text in must and pass every filter;
# on_sale items rank higher; discontinued items never appear

PUT /articles
{
  "settings": { "analysis": { "analyzer": {
    "folded_english": {
      "type": "custom",
      "char_filter": ["html_strip"],
      "tokenizer": "standard",
      "filter": ["lowercase", "asciifolding", "stop", "porter_stem"]
    } } } },
  "mappings": { "properties": {
    "body": { "type": "text", "analyzer": "folded_english" } } }
}

POST /articles/_analyze
{ "analyzer": "folded_english", "text": "<p>The Cafés are RUNNING late</p>" }
# tokens: "cafe", "run", "late"

POST /orders/_pit?keep_alive=1m
# { "id": "46ToAwMDaWR5BXV1..." }

GET /_search
{
  "size": 100,
  "query": { "term": { "status": "paid" } },
  "pit": { "id": "46ToAwMDaWR5BXV1...", "keep_alive": "1m" },
  "sort": [ { "placed_at": "desc" } ]
}
# each hit ends with "sort": [1760700000000, 4294967298]

GET /_search
{
  "size": 100,
  "query": { "term": { "status": "paid" } },
  "pit": { "id": "46ToAwMDaWR5BXV1...", "keep_alive": "1m" },
  "sort": [ { "placed_at": "desc" } ],
  "search_after": [1760700000000, 4294967298]
}

DELETE /_pit
{ "id": "46ToAwMDaWR5BXV1..." }

PUT /carts
{ "mappings": { "properties": {
  "items": { "type": "nested", "properties": {
    "sku": { "type": "keyword" }, "qty": { "type": "integer" } } } } } }

PUT /carts/_doc/1?refresh=true
{ "items": [ { "sku": "PEN", "qty": 1 }, { "sku": "PAD", "qty": 9 } ] }

GET /carts/_search
{ "query": { "nested": { "path": "items", "query": { "bool": { "filter": [
    { "term": { "items.sku": "PEN" } },
    { "range": { "items.qty": { "gt": 5 } } } ] } } } } }
# 0 hits: no single item is PEN with qty > 5
# (with a plain object mapping this would wrongly return the cart)

PUT /products-v4
{ "mappings": { "properties": {
  "name":  { "type": "text", "analyzer": "english" },
  "price": { "type": "scaled_float", "scaling_factor": 100 } } } }

POST /_reindex?wait_for_completion=false&slices=auto
{ "source": { "index": "products-v3" }, "dest": { "index": "products-v4" } }
# { "task": "oTUltX4IQMOUUVeiohTt8A:12345" }
GET /_tasks/oTUltX4IQMOUUVeiohTt8A:12345

POST /_aliases
{ "actions": [
  { "remove": { "index": "products-v3", "alias": "products" } },
  { "add":    { "index": "products-v4", "alias": "products" } } ] }
# both actions apply atomically: clients never see a gap

GET /_alias/products

PUT /docs
{ "mappings": { "properties": {
  "text":      { "type": "text" },
  "embedding": { "type": "dense_vector", "dims": 3, "similarity": "cosine" } } } }

PUT /docs/_doc/1?refresh=true
{ "text": "low-cost airfare deals", "embedding": [0.9, 0.1, 0.2] }

GET /docs/_search
{
  "retriever": { "rrf": { "retrievers": [
    { "standard": { "query": { "match": { "text": "cheap flights" } } } },
    { "knn": { "field": "embedding", "query_vector": [0.88, 0.15, 0.2],
               "k": 10, "num_candidates": 100 } }
  ] } }
}
# doc 1 is returned via the kNN retriever even though no words match
# (real embeddings have hundreds of dimensions)

# all docs of tenant acme go to one shard; searches with the same routing hit only it
PUT /tickets/_doc/42?routing=acme
{ "tenant": "acme", "title": "Printer on fire" }

GET /tickets/_search?routing=acme
{ "query": { "match": { "title": "printer" } } }

# global IDF for small or skewed indices
GET /tickets/_search?search_type=dfs_query_then_fetch
{ "query": { "match": { "title": "printer" } } }

# where does the time go, per shard?
GET /tickets/_search
{ "profile": true, "query": { "match": { "title": "printer" } } }
# "profile": { "shards": [ { "id": "[node-1][tickets][0]", "searches": [ ... ] } ] }
